// 🧪 BOTI'S DIAGNOSTICS — week 1
//
// ⚠️ Do not edit this file. These are Doña Carmen's exact orders.
// Red = the skill is not installed yet. Green = installed!
//
// Run the diagnostics with:   npm run week1

const {
  getItemAt,
  countStock,
  hasItem,
  addItems,
  removeItem,
  makeShelfLabels,
  mergeDeliveries,
} = require("./skills");

// 🔦 Q0 — Shelf map -----------------------------------------------

test("Q0: finds the item at a position in the list", () => {
  const currentOutput = getItemAt(["churros", "tortilla", "horchata"], 0);
  const targetOutput = "churros";
  expect(currentOutput).toEqual(targetOutput);
});

test("Q0: finds items at other positions too", () => {
  expect(getItemAt(["churros", "tortilla", "horchata"], 2)).toEqual("horchata");
});

test("Q0: says 'nothing there' when the position is empty", () => {
  expect(getItemAt(["churros", "tortilla"], 5)).toEqual("nothing there");
});

// 🧮 Q1 — Stock-take ----------------------------------------------

test("Q1: counts how many of an item are in stock", () => {
  const stockList = ["churros", "tortilla", "churros", "churros"];
  expect(countStock(stockList, "churros")).toEqual(3);
});

test("Q1: counts 0 when the item is not in stock", () => {
  expect(countStock(["tortilla", "horchata"], "churros")).toEqual(0);
});

test("Q1: an empty stock list has 0 of everything", () => {
  expect(countStock([], "churros")).toEqual(0);
});

// ❓ Q2 — The customer's question ---------------------------------

test("Q2: knows if an item is in stock", () => {
  expect(hasItem(["churros", "tortilla", "croissant"], "tortilla")).toEqual(
    true,
  );
});

test("Q2: knows if an item is missing", () => {
  expect(hasItem(["churros", "tortilla"], "croissant")).toEqual(false);
});

// 📦 Q3 — Restock day ---------------------------------------------

test("Q3: restocking gives a NEW list with the new items at the end", () => {
  const carmensList = ["churros", "tortilla"];
  const delivery = ["croissant", "ensaimada"];
  const targetOutput = ["churros", "tortilla", "croissant", "ensaimada"];
  expect(addItems(carmensList, delivery)).toEqual(targetOutput);
});

test("Q3: Doña Carmen's original list must stay exactly as she wrote it", () => {
  const carmensList = ["churros", "tortilla"];
  addItems(carmensList, ["croissant"]);
  // This is the test from your prep: the input must not change.
  expect(carmensList).toEqual(["churros", "tortilla"]);
});

// 🐞 Q4 — BUG HUNT: The Great Horchata Recall ---------------------

test("Q4: a recall pulls EVERY matching item off the shelves", () => {
  const shelves = ["horchata", "tortilla", "horchata"];
  expect(removeItem(shelves, "horchata")).toEqual(["tortilla"]);
});

test("Q4: recalling a product that isn't there steals NOTHING", () => {
  const shelves = ["churros", "tortilla"];
  expect(removeItem(shelves, "croissant")).toEqual(["churros", "tortilla"]);
});

test("Q4: Carmen's wall list survives the recall untouched", () => {
  const carmensList = ["horchata", "tortilla", "horchata"];
  removeItem(carmensList, "horchata");
  expect(carmensList).toEqual(["horchata", "tortilla", "horchata"]);
});

// 🏷️ Q5 — The label gun -------------------------------------------

test("Q5: prints a shelf label for every item, in order", () => {
  expect(makeShelfLabels(["churros", "tortilla"])).toEqual([
    "SHELF: CHURROS",
    "SHELF: TORTILLA",
  ]);
});

test("Q5: an empty stock list gets an empty set of labels", () => {
  expect(makeShelfLabels([])).toEqual([]);
});

// 🏆 Q6 — BOSS: Double delivery -----------------------------------

test("Q6: merges two deliveries with no duplicates", () => {
  const morning = ["churros", "tortilla"];
  const afternoon = ["tortilla", "horchata"];
  const targetOutput = ["churros", "tortilla", "horchata"];
  expect(mergeDeliveries(morning, afternoon)).toEqual(targetOutput);
});

test("Q6: both delivery notes stay exactly as the warehouse wrote them", () => {
  const morning = ["churros", "tortilla"];
  const afternoon = ["tortilla", "horchata"];
  mergeDeliveries(morning, afternoon);
  expect(morning).toEqual(["churros", "tortilla"]);
  expect(afternoon).toEqual(["tortilla", "horchata"]);
});
